/* hw_world.c -- the SDK-world glue of the overlays and the soft reset: the linker's section symbols (port/hwgen/overlay_sections.c, generated by
 * tools/overlay_map.py) into hw_ovl, the HWDEV_Overlay* hooks of the patched fs_overlay.c, and HWOS_ResetSystem into hw_boot.
 * Which state a reset restores: ONLY the objects under port/obj (game + NitroSDK/NitroSystem/DWC); the hardware layer (port/hwobj), libctru and
 * newlib are linked outside every restore range (tools/overlay_map.py's patterns; a private link check verifies it on every link). */
#include <assert.h>
#include <string.h>

#include <nitro.h>

#include "hw_boot.h"
#include "hw_ctr.h"
#include "hw_devs.h"
#include "hw_log.h"
#include "hw_os.h"
#include "hw_ovl.h"
#include "hw_sys.h"
#include "hw_world.h"
#include <hw_dev_hooks.h>
#include <hw_os_hooks.h>

#define GAME_STACK_BYTES 0x100000u   /* the DS main stack was far smaller; the host threads of the SDK scheduler are separate */

extern const HwOvlSyms g_hw_ovl_syms[HW_OVL_COUNT];
extern const HwOvlSyms g_hw_main_syms;
extern char *const g_hw_ovl_pristine_start;
extern char *const g_hw_ovl_pristine_end;

HwOvlSection g_overlay_sections[HW_OVL_COUNT];
static HwOvl s_ovl;
static HwBoot s_boot;
static int s_up;
static uint32_t s_eoo_refused;   /* resets that carried a nested-ROM request */

static void world_reseed(void *u)
{
    (void)u;
    hw_sys_reseed();         /* memory arrays, registers, DTCM zeroed; system page filled (this also re-reads the card header) */
    hw_os_reset();           /* CPU shadow, tick, pump */
    hw_devs_reset();         /* PXI loopback, DMA, card transfer */
    hw_dwc_reset();          /* stand-in statics that point into the previous boot's heap */
    hw_ppwlobby_reset();
    HWLOG("soft reset: world re-seeded (boot %u)", (unsigned)s_boot.boots);
}

int hw_world_init(void (*entry)(void))
{
    static const HwBootOps ops = { world_reseed, NULL };
    int32_t used;

    assert(entry != NULL);
    assert(!s_up);
    used = hwovl_init(&s_ovl, g_overlay_sections, HW_OVL_COUNT, g_hw_ovl_syms, &g_hw_main_syms, (uint8_t *)g_hw_ovl_pristine_start,
                      (uint32_t)(g_hw_ovl_pristine_end - g_hw_ovl_pristine_start));
    if (used < 0) {
        hwctr_fatal("overlay sections inconsistent with the pristine buffer (tools/overlay_map.py)");
        return -1;
    }
    hwboot_init(&s_boot, &s_ovl, hw_os_ctx(), &ops, entry, (volatile uint32_t *)HW_RESET_PARAMETER_BUF, GAME_STACK_BYTES);
    s_up = 1;
    HWLOG("overlays: main .data %u B, %u overlays; pristine copies %d of %d B", (unsigned)s_ovl.main.data_size, (unsigned)s_ovl.count, (int)used,
          (int)s_ovl.pristine_size);
    return 0;
}

int hw_world_run(void)
{
    assert(s_up);
    return hwboot_start(&s_boot);
}

const HwOvl *hw_world_ovl(void)
{
    return &s_ovl;
}

/* ---- overlays ------------------------------------------------------------------------------------------------------------------ */
static const char *ovl_name(uint32_t id)
{
    return id < HW_OVL_COUNT ? g_hw_ovl_syms[id].name : "?";
}

void HWDEV_OverlayLoad(uint32_t id)
{
    HWCOUNT("FS_LoadOverlayImage");
    hwtrace("ovl: LOAD %u %s", (unsigned)id, ovl_name(id));
    if (!s_up || hwovl_load(&s_ovl, id) != 0) {
        HWLOG("FS_LoadOverlay(%u) ignored: %s", (unsigned)id, s_up ? "bad id" : "hw_world_init not run");
    }
}

void HWDEV_OverlayStart(uint32_t id)
{
    int n = s_up ? hwovl_start(&s_ovl, id) : -1;

    HWCOUNT("FS_StartOverlay");
    if (n < 0) {
        HWLOG("FS_StartOverlay(%u) ignored: %s", (unsigned)id, s_up ? "bad id" : "hw_world_init not run");
    }
}

void HWDEV_OverlayUnload(uint32_t id)
{
    HWCOUNT("FS_UnloadOverlayImage");
    hwtrace("ovl: UNLOAD %u %s", (unsigned)id, ovl_name(id));
    if (!s_up || hwovl_unload(&s_ovl, id) != 0) {
        HWLOG("FS_UnloadOverlay(%u) ignored: %s", (unsigned)id, s_up ? "bad id" : "hw_world_init not run");
    }
}

/* ---- soft reset ----------------------------------------------------------------------------------------------------------------- */
static uint32_t s_resets;

void HWOS_ResetSystem(void (*doReset)(void))
{
    HWCOUNT("OS: HWOS_ResetSystem");
    (void)doReset;   /* OSi_DoResetSystem would wait for the ARM7 and reload the ROM header; the hardware layer does both itself */
    /* every reset is traced (HWLOG keeps one line per call site, which hid the second reset's RESET_ERROR parameter, review 1.6 F5); boot: RESET param=0 is
       RESET_CLEAN (the first boot and a START+SELECT+L+R reset), param=1 is RESET_ERROR (the network-error recovery) */
    s_resets++;
    hwtrace("boot: RESET param=%u n=%u reason=%s", (unsigned)*(volatile uint32_t *)HW_RESET_PARAMETER_BUF, (unsigned)s_resets,
            s_resets == 1u ? "power-on" : (*(volatile uint32_t *)HW_RESET_PARAMETER_BUF == 1u ? "RESET_ERROR (communication error recovery)" : "soft reset"));
    HWLOG("HWOS_ResetSystem: soft reset (parameter %08x)", (unsigned)*(volatile uint32_t *)HW_RESET_PARAMETER_BUF);
    if (!s_up) {
        hwctr_fatal("soft reset before hw_world_init");
        return;
    }
    if (*(volatile uint32_t *)HW_ROM_BASE_OFFSET_BUF != 0u) {
        /* "Connect to Wii" (RebootAndLoadROM("data/eoo.dat"), boot.c) asks the loader to boot a second ROM image. The DS jumps to that image;
           we have none, and by here OS_ResetSystem has already masked every IRQ but the FIFO (returning would hang the game). So the nested boot
           is refused and the request degrades to the ordinary soft reset: Platinum restarts at its logos/title screen, the save is untouched
           (the backup flash survives a reset), nothing is lost but the unsaved session. */
        HWLOG("nested ROM boot (data/eoo.dat, image at %08x) is unsupported: refused, plain soft reset to the title instead",
              (unsigned)*(volatile uint32_t *)HW_ROM_BASE_OFFSET_BUF);
        s_eoo_refused++;
    }
    hwlog_dump();
    if (hwboot_reset(&s_boot, *(volatile uint32_t *)HW_RESET_PARAMETER_BUF) != 0) {
        hwctr_fatal("soft reset: no host thread for the new NitroMain");
    }
}
